def flatten(nested):
    result = []
    for sublist in nested:
        result.extend(sublist)
    return result


def unique_ordered(lst):
    seen = set()
    result = []
    for item in lst:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result


def group_consecutive(lst):
    if not lst:
        return []
    groups = [[lst[0]]]
    for item in lst[1:]:
        if item == groups[-1][-1]:
            groups[-1].append(item)
        else:
            groups.append([item])
    return groups
